arguments.content:
/* ShiftWise — Custom Styles */

/* Smooth scrolling */
html { scroll-behavior: smooth; }

/* Mobile nav drawer */
.nav-drawer {
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}
.nav-drawer.open {
  transform: translateX(0);
}
.nav-overlay {
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.3s ease;
}
.nav-overlay.open {
  opacity: 1;
  pointer-events: auto;
}

/* Testimonial carousel */
.testimonial-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.testimonial-slide {
  min-width: 100%;
  padding: 0 1rem;
  box-sizing: border-box;
}

/* FAQ accordion */
.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}
.faq-answer.open {
  max-height: 500px;
}
.faq-chevron {
  transition: transform 0.3s ease;
}
.faq-chevron.open {
  transform: rotate(180deg);
}

/* Pricing toggle */
.toggle-track {
  transition: background-color 0.3s ease;
}
.toggle-knob {
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

/* Count-up animation helper */
.stat-number {
  font-variant-numeric: tabular-nums;
}

/* Scroll fade-in */
.fade-up {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.7s ease, transform 0.7s ease;
}
.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* Hero gradient overlay */
.hero-gradient {
  background: linear-gradient(135deg, #0A1628 0%, #0051C3 100%);
}

/* CTA gradient */
.cta-gradient {
  background: linear-gradient(135deg, #0051C3 0%, #003080 50%, #0A1628 100%);
}

/* Accent bar */
.accent-bar {
  width: 60px;
  height: 4px;
  background: #DE5052;
  border-radius: 2px;
}

/* Card hover */
.feature-card {
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.feature-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.1);
}

/* Pricing card */
.pricing-card {
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}
.pricing-card:hover {
  transform: translateY(-6px);
}
.pricing-card.featured {
  border: 2px solid #0051C3;
}

/* Button hover states */
.btn-primary {
  background: #0051C3;
  transition: background 0.2s ease, transform 0.2s ease, box-shadow 0.2s ease;
}
.btn-primary:hover {
  background: #003D94;
  transform: translateY(-1px);
  box-shadow: 0 4px 12px rgba(0, 81, 195, 0.4);
}
.btn-secondary {
  transition: background 0.2s ease, transform 0.2s ease;
}
.btn-secondary:hover {
  background: rgba(255, 255, 255, 0.15);
  transform: translateY(-1px);
}

/* Integration logo card */
.integration-card {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.integration-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.08);
}

/* Form styles */
.form-input {
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}
.form-input:focus {
  border-color: #0051C3;
  box-shadow: 0 0 0 3px rgba(0, 81, 195, 0.15);
  outline: none;
}
.form-input.error {
  border-color: #DE5052;
  box-shadow: 0 0 0 3px rgba(222, 80, 82, 0.15);
}
.form-error {
  color: #DE5052;
  font-size: 0.85rem;
  margin-top: 0.25rem;
  display: none;
}
.form-error.show {
  display: block;
}

/* Success message */
.success-message {
  animation: slideIn 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
@keyframes slideIn {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

/* Team member card */
.team-card {
  transition: transform 0.3s ease;
}
.team-card:hover {
  transform: translateY(-4px);
}

/* Nav link underline animation */
.nav-link {
  position: relative;
}
.nav-link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 2px;
  background: #0051C3;
  transition: width 0.3s ease;
}
.nav-link:hover::after {
  width: 100%;
}

/* Sticky header */
.site-header {
  transition: background 0.3s ease, box-shadow 0.3s ease;
}
.site-header.scrolled {
  background: rgba(255, 255, 255, 0.98);
  box-shadow: 0 1px 12px rgba(0, 0, 0, 0.08);
}

/* Carousel dots */
.carousel-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #CBD5E1;
  transition: background 0.3s ease, transform 0.3s ease;
  cursor: pointer;
}
.carousel-dot.active {
  background: #0051C3;
  transform: scale(1.3);
}

/* How-it-works step connector */
.step-connector {
  position: absolute;
  top: 28px;
  left: calc(50% + 28px);
  width: calc(100% - 56px);
  height: 2px;
  background: #E2E8F0;
}

